select '1..3' as tap;
create function pg_temp.require(ok boolean)returns void language plpgsql as $$begin perform set_config('p14.assert',(coalesce(nullif(current_setting('p14.assert',true),''),'0')::int+1)::text,true);if ok is distinct from true then raise exception 'Synergy assertion failed %',current_setting('p14.assert');end if;end$$;
create function pg_temp.rejects(command text,code text)returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'Expected synergy rejection %',code;end$$;
create function pg_temp.terms()returns jsonb language sql as $$select '{"output":"Fictional negotiated output","criteria":"Fictional explicit acceptance criteria","effort":"medium","dueOn":"2027-04-10","reason":"Synthetic committee request","sourceManifestIds":["eeeeeeee-eeee-4eee-8eee-eeeeeeeeee14"]}'::jsonb$$;
create function pg_temp.pv()returns integer language sql as $$select(public.read_deliverable('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa7')->>'version')::integer$$;
grant execute on function pg_temp.require(boolean),pg_temp.rejects(text,text),pg_temp.terms(),pg_temp.pv()to authenticated;
grant execute on function pg_temp.rejects(text,text)to anon;
